class CompleteProductionRequest extends FormRequest { public function authorize():bool{return $this->user()->hasPermission('production.complete');} public function rules():array{return ['completed_at'=>['required','date'],'actual_dough_quantity'=>['required','numeric','gt:0','decimal:0,6'],'waste_quantity'=>['required','numeric','min:0','decimal:0,6'],'consumptions'=>['required','array','min:1'],'consumptions.*.consumption_id'=>['required','ulid','distinct','exists:production_consumptions,id'],'consumptions.*.actual_quantity'=>['required','numeric','min:0','decimal:0,6'],'consumptions.*.difference_reason'=>['nullable','string','max:2000'],'outputs'=>['required','array','min:1'],'outputs.*.compatible_product_id'=>['required','ulid','distinct','exists:recipe_compatible_products,id'],'outputs.*.quantity'=>['required','numeric','gt:0','decimal:0,6'],'outputs.*.dough_quantity'=>['required','numeric','gt:0','decimal:0,6'],'labor_hours'=>['sometimes','array'],'labor_hours.*.person_id'=>['required','ulid','exists:people,id'],'labor_hours.*.hours'=>['required','numeric','gt:0','decimal:0,4'],'labor_hours.*.hourly_rate'=>['required','integer','min:0'],'manual_labor_amount'=>['nullable','integer','min:0'],'manual_labor_reason'=>['nullable','string','max:2000'],'manual_labor_authorization_id'=>['nullable','ulid','exists:authorization_requests,id']];} }
